/// <reference types="vite/client" />

declare const __APP_VERSION__: string;

declare module '*.svg' {
  const content: string;
  export default content;
}

declare module '*.png' {
  const content: string;
  export default content;
}

declare module '*.jpg' {
  const content: string;
  export default content;
}

interface Window {
  electronAPI?: {
    platform: string;
    version: string;
    showReminderNotification: (payload: { title: string; body: string; silent: boolean }) => Promise<boolean>;
  };
}
